import{_ as i,C as a,o as d,c,ag as e,E as s,j as o,a as r}from"./chunks/framework.CtWPcAmt.js";const _=JSON.parse('{"title":"Product Discounts","description":"","frontmatter":{},"headers":[],"relativePath":"marketing/product-discounts.md","filePath":"marketing/product-discounts.md","lastUpdated":1786088921000}'),u={name:"marketing/product-discounts.md"};function l(p,t,g,h,m,f){const n=a("ImagePopup");return d(),c("div",null,[t[0]||(t[0]=e('<h1 id="product-discounts" tabindex="-1">Product Discounts <a class="header-anchor" href="#product-discounts" aria-label="Permalink to &quot;Product Discounts&quot;">​</a></h1><p>Product Discounts are automatic price reductions a seller applies to their <strong>own catalog</strong>. Once a discount is active, every matching product shows its reduced price on the storefront — no coupon needed. Sellers can also opt into discounts the admin publishes for everyone.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to create a product discount, tab by tab</li><li>How the conditions builder targets the right products</li><li>How to manage discounts and join admin-published ones</li></ul></div><h2 id="creating-a-product-discount" tabindex="-1">Creating a product discount <a class="header-anchor" href="#creating-a-product-discount" aria-label="Permalink to &quot;Creating a product discount&quot;">​</a></h2><p>From the Seller Panel, open <strong>Marketing → Product Discounts</strong> and select <strong>Create Product Discount</strong>. The form has three tabs — <strong>Discount</strong>, <strong>Details</strong>, and <strong>Advanced</strong> — and the tab strip flags any tab that still has errors.</p><h3 id="discount" tabindex="-1">Discount <a class="header-anchor" href="#discount" aria-label="Permalink to &quot;Discount&quot;">​</a></h3><p>Choose <strong>how</strong> the reduction is applied and by how much:</p>',7)),s(n,{src:"/images/product-discounts/discount.png",alt:"Product discount — Discount tab"}),t[1]||(t[1]=o("ul",null,[o("li",null,[o("strong",null,"Percentage off the price"),r(" — take a percentage off every matching product (for example, 15%).")]),o("li",null,[o("strong",null,"Fixed amount off the price"),r(" — take a set amount off each matching product (for example, $5).")]),o("li",null,[o("strong",null,"Discount Amount"),r(" — the percentage (max 100) or fixed value to apply.")])],-1)),t[2]||(t[2]=o("h3",{id:"details",tabindex:"-1"},[r("Details "),o("a",{class:"header-anchor",href:"#details","aria-label":'Permalink to "Details"'},"​")],-1)),t[3]||(t[3]=o("p",null,"Give the discount its identity and schedule:",-1)),s(n,{src:"/images/product-discounts/details.png",alt:"Product discount — Details tab"}),t[4]||(t[4]=e('<ul><li><strong>Name</strong> and an optional <strong>Description</strong>.</li><li><strong>Marketing Time</strong> — a <strong>Starts From</strong> and <strong>Ends Till</strong> date window (leave empty to run indefinitely).</li></ul><h3 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h3><p>Decide <strong>which products</strong> the discount applies to and how it behaves:</p>',3)),s(n,{src:"/images/product-discounts/advanced.png",alt:"Product discount — Advanced tab with conditions"}),t[5]||(t[5]=e('<ul><li><strong>Conditions</strong> — a rule builder. Add one or more conditions, each an <strong>Attribute → Operator → Value</strong> row (for example, <em>Category → Contains → Summer</em>, or <em>Price → greater than → 50</em>). Attributes cover the product&#39;s category, attribute family, and every product attribute; operators adapt to the attribute type (equals, contains, greater/less than, and so on).</li><li><strong>All conditions true / Any conditions true</strong> — whether a product must match every condition or just one.</li><li><strong>Priority</strong> — which discount wins when several could apply to the same product.</li><li><strong>End Other Rules</strong> — set to <strong>Yes</strong> to stop lower-priority discounts once this one matches.</li><li><strong>Channels</strong> and <strong>Customer Groups</strong> — where and for whom the discount applies (defaults to all of yours).</li><li><strong>Status</strong> — turn the discount on or off.</li></ul><p>Select <strong>Save Product Discount</strong>, and the reduction applies automatically to your matching products on the storefront.</p><h2 id="managing-discounts" tabindex="-1">Managing discounts <a class="header-anchor" href="#managing-discounts" aria-label="Permalink to &quot;Managing discounts&quot;">​</a></h2><p>The <strong>Product Discounts</strong> list shows every discount you&#39;ve created with its <strong>priority</strong>, dates, and status. From there you can <strong>Edit</strong> a discount or <strong>Delete</strong> it — deleting or disabling one immediately restores the affected products to their normal price.</p><h2 id="joining-an-admin-product-discount" tabindex="-1">Joining an admin product discount <a class="header-anchor" href="#joining-an-admin-product-discount" aria-label="Permalink to &quot;Joining an admin product discount&quot;">​</a></h2><p>The admin can publish product discounts for sellers to opt into. From <strong>Marketing → Product Discounts</strong>, select <strong>Join Product Discounts</strong> to see what&#39;s available.</p>',6)),s(n,{src:"/images/product-discounts/join.png",alt:"Join admin product discounts"}),t[6]||(t[6]=e('<ul><li><strong>View</strong> a discount to see its full terms (conditions, actions, schedule) read-only.</li><li><strong>Enroll</strong> your products individually or with the <strong>bulk enroll</strong> action; <strong>Withdraw</strong> the same way to leave.</li><li>Each enrollment shows a status — <strong>Approved</strong>, <strong>Pending</strong>, or <strong>Disapproved</strong>. Depending on the admin&#39;s setting, joining is either auto-approved or waits for the admin to approve it.</li></ul><p>Once enrolled and approved, the admin&#39;s discount reprices your listings for as long as you stay joined.</p><div class="info custom-block"><p class="custom-block-title">Admin controls this</p><p>Joining admin discounts is governed by an admin capability. If the admin turns off catalog-rule joining, joined discounts stop repricing your products.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Product Discounts change a product&#39;s <strong>shown price</strong>. To reward the <strong>whole cart</strong> — or to gate an offer behind a coupon code — use <a href="/marketing/checkout-deals">Checkout Deals</a>. For a quick scheduled price cut on individual products, the <a href="/pricing/manage-pricing">Manage Pricing</a> special price is often simpler.</p></div>',4))])}const v=i(u,[["render",l]]);export{_ as __pageData,v as default};
